import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.CUozl7Kn.js";var i=JSON.parse(`{"title":"Guest Book Embedding Example","description":"","frontmatter":{"id":"guide.guest-book-embedding-example","title":"Guest Book Embedding Example","describes":["proposal.0001"]},"headers":[],"relativePath":"guides/guest-book-embedding-example.md","filePath":"guides/guest-book-embedding-example.md"}`),a={name:`guides/guest-book-embedding-example.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="guest-book-embedding-example" tabindex="-1">Guest Book Embedding Example <a class="header-anchor" href="#guest-book-embedding-example" aria-label="Permalink to “Guest Book Embedding Example”">​</a></h1><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><p><code>bento-guestbook-host</code> is a small Rust application that runs the Remix 3 guest book inside its own process. It is the worked example for embedding Bento: the same runtime, module loader, TypeScript transform, and Node compatibility that the <code>bento</code> command uses, driven from Rust instead of from a command line.</p><p>The example demonstrates four embedding features through one application:</p><ul><li><strong>A host module.</strong> The host registers <code>host:guestbook</code> for its runtime instance before loading the application. The guest book&#39;s embedded entrypoint, <code>server.embedded.ts</code>, imports it and awaits <code>list()</code> and <code>append({ name, message })</code>. The module is ordinary embedding API: a name, and asynchronous Rust functions that take and return JSON values. Nothing in the runtime knows what a guest book is.</li><li><strong>Rust-owned storage.</strong> Entries live in a SQLite database that Rust opens through <code>rusqlite</code>, with the host&#39;s own table (<code>id</code>, <code>name</code>, <code>message</code>, <code>createdAt</code>). The guest never learns the database path, has no write grant, and cannot read the file through <code>node:fs</code>; it only sees the entries the host chooses to return.</li><li><strong>Grants and lifecycle control.</strong> The host decides what the guest may do: read the project and the package lookup locations above it, open network listeners, see <code>PORT</code>, <code>NODE_ENV</code>, and <code>DATABASE_URL</code>, and load the native compiler addons under the project&#39;s <code>node_modules</code>. The host also owns shutdown: Ctrl-C or <code>SIGTERM</code> to the host asks the runtime to stop, waits for the application&#39;s own <code>SIGTERM</code> handler, and reports the outcome. The runtime installs no OS signal handlers of its own.</li><li><strong>Persistence across instances.</strong> Because Rust owns the database, entries survive disposing and recreating the runtime and restarting the host process. <code>entries</code> reads them back without starting a runtime at all.</li></ul><p>The stock <code>bento</code> command does not provide <code>host:guestbook</code>; <code>bento run server.embedded.ts</code> fails to resolve the import. The CLI entrypoint, <code>server.ts</code>, keeps the application&#39;s <code>node:sqlite</code> storage instead.</p><h2 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to “How to use it”">​</a></h2><h3 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to “Build”">​</a></h3><p>The example is a workspace member crate. Every command in this guide runs from the repository root.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">cargo</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> build</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --release</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> -p</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> bento_guestbook_host</span></span></code></pre></div><p>The executable is <code>target/release/bento-guestbook-host</code>; Cargo does not put it on <code>PATH</code>, so the commands below name it by that path. Its build script exports the Node-API symbols that the guest book&#39;s native compiler packages (<code>oxc-transform</code>, <code>oxc-parser</code>, <code>oxc-minify</code>, <code>oxc-resolver</code>, <code>lightningcss</code>) resolve when they load.</p><h3 id="prepare-a-project" tabindex="-1">Prepare a project <a class="header-anchor" href="#prepare-a-project" aria-label="Permalink to “Prepare a project”">​</a></h3><p>The host runs a guest book project whose dependencies are installed. For the fixture in this repository, install them in place, still from the repository root:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">pnpm</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --dir</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> fixtures/remix-guest-book</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> install</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --frozen-lockfile</span></span></code></pre></div><p>The host does not install packages or run migrations. The application&#39;s own <code>db/</code> migrations belong to the <code>node:sqlite</code> path; the host creates its own table on first use.</p><h3 id="serve" tabindex="-1">Serve <a class="header-anchor" href="#serve" aria-label="Permalink to “Serve”">​</a></h3><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">target/release/bento-guestbook-host</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> serve</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --project</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> fixtures/remix-guest-book</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --database</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> /tmp/guest-book.db</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--project &lt;dir&gt;</code></td><td>The guest book project: the fixture or a copy of it with installed dependencies. Required.</td></tr><tr><td><code>--database &lt;path&gt;</code></td><td>The SQLite file the host owns, outside every path the guest may read. Created, with its table, when it does not exist. Required.</td></tr><tr><td><code>--port &lt;N&gt;</code></td><td>The port the application listens on. Default <code>1612</code>, the application&#39;s own default.</td></tr><tr><td><code>--read-only</code></td><td>Refuse <code>append</code> at the Rust boundary. <code>list</code> still works. The database must already exist.</td></tr><tr><td><code>--mode development|production</code></td><td>The <code>NODE_ENV</code> the guest sees. <code>development</code> logs each request and serves unminified assets with source maps; <code>production</code> serves minified, fingerprinted, immutable assets. Default <code>production</code>.</td></tr></tbody></table><p>The host starts <code>server.embedded.ts</code> with these grants and nothing more:</p><ul><li><strong>Read:</strong> the project directory, plus Node&#39;s package lookup locations above it: <code>&lt;ancestor&gt;/node_modules</code> for the project and each of its ancestors up to <code>/</code>. The application&#39;s asset discovery probes those directories with <code>fs.realpathSync</code> while it resolves optional packages, and the runtime keeps a probe outside the grant a permission error rather than pretending the directory is absent. The host computes the list with <code>bento_runtime::package_lookup_paths</code> and grants it explicitly; the runtime adds no permissions on its own.</li><li><strong>Write:</strong> nothing. The application has nothing to write, because the host owns the database.</li><li><strong>Net:</strong> all, so the application can listen on its port.</li><li><strong>Env:</strong> <code>PORT</code>, <code>NODE_ENV</code>, and <code>DATABASE_URL</code>. The host sets the first two; it never sets <code>DATABASE_URL</code>, so the guest sees it as undefined and the database location stays on the Rust side.</li><li><strong>Addons:</strong> <code>&lt;project&gt;/node_modules</code>, where the native compiler packages live.</li></ul><p>The read grant is why the database must lie outside the project and outside every <code>node_modules</code> directory beside or above it: a store under any of those paths would be readable through <code>node:fs</code> like any other file there. <code>serve</code> refuses such a <code>--database</code> before it opens anything, naming the granted path the store would fall under, and compares resolved paths so a symlink cannot hide the placement.</p><p>Launch the host without <code>NODE_PATH</code> in its environment. The guest book&#39;s native resolver reads that variable from the host process, not from the guest&#39;s environment, and a value pointing at another project&#39;s packages sends resolution outside the project and into a permission error under these grants.</p><p>Open <code>http://localhost:1612</code>. The page renders the saved entries and the sign form; the module scripts, import map, and stylesheet it references are served by the same instance. A valid submission answers <code>303 See Other</code> with <code>Location: /</code>, and the next page shows the entry and a blank form; blank or over-long fields answer <code>400</code> with field errors and write nothing. Plain HTML submission works without browser JavaScript.</p><p>Press Ctrl-C (or send <code>SIGTERM</code>) to stop. The host takes Ctrl-C and <code>SIGTERM</code> over before it starts the runtime, so a signal that arrives while the application is still starting ends the instance the same way as one that arrives while it serves. The host asks the runtime to shut down, the application&#39;s <code>SIGTERM</code> handler closes its server and exits, and the host prints the outcome on one line, or reports the error when the shutdown failed:</p><table tabindex="0"><thead><tr><th>Printed</th><th>Meaning</th><th>Host exit status</th></tr></thead><tbody><tr><td><code>shutdown: graceful (exit code N)</code></td><td>The application exited itself during the shutdown, with <code>N</code>. The guest book&#39;s handler exits with <code>0</code>.</td><td><code>N</code></td></tr><tr><td><code>shutdown: graceful (closed by the host on SIGTERM)</code></td><td>The application had no handler for the signal, so the runtime closed its listeners and cancelled its work.</td><td><code>143</code> after <code>SIGTERM</code>, <code>130</code> after Ctrl-C, as a process ended by that signal reports</td></tr><tr><td><code>shutdown: interrupted</code></td><td>JavaScript had to be terminated at the five-second deadline.</td><td><code>1</code></td></tr><tr><td><code>shutdown: timed out</code></td><td>Native code did not yield by the deadline.</td><td><code>1</code></td></tr><tr><td><code>error: &lt;error&gt;</code> on standard error, with no <code>shutdown:</code> line</td><td>The application failed during the shutdown, for example its <code>SIGTERM</code> handler threw. The runtime reports that failure as the instance&#39;s outcome, so the host prints it as it prints any guest error, naming the entry and where the error was thrown.</td><td><code>1</code></td></tr></tbody></table><p>After a graceful shutdown the port is free to bind again immediately, and the whole shutdown completes within the five-second deadline.</p><h3 id="inspect-the-store" tabindex="-1">Inspect the store <a class="header-anchor" href="#inspect-the-store" aria-label="Permalink to “Inspect the store”">​</a></h3><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">target/release/bento-guestbook-host</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> entries</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --database</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> /tmp/guest-book.db</span></span></code></pre></div><p>This reads the Rust-owned table directly and prints one JSON object per line, oldest first, with the same fields the host module returns to the guest:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">{</span></span>
<span class="line"><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">    &quot;id&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: </span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">1</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">,</span></span>
<span class="line"><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">    &quot;name&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: </span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">&quot;Ada Lovelace&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">,</span></span>
<span class="line"><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">    &quot;message&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: </span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">&quot;Hello from 1843&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">,</span></span>
<span class="line"><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">    &quot;createdAt&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: </span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">&quot;2026-10-10T18:30:05Z&quot;</span></span>
<span class="line"><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">}</span></span></code></pre></div><p>No runtime starts, so this is how a reviewer confirms that persistence is Rust&#39;s: sign the guest book, stop the host, and the entries are still in the file. Starting the host again on the same <code>--database</code> serves them. An empty store prints nothing; a path with no database is an error, and <code>entries</code> never creates one.</p><h3 id="demonstrate-read-only" tabindex="-1">Demonstrate read-only <a class="header-anchor" href="#demonstrate-read-only" aria-label="Permalink to “Demonstrate read-only”">​</a></h3><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">target/release/bento-guestbook-host</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> serve</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --project</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> fixtures/remix-guest-book</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --database</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> /tmp/guest-book.db</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --read-only</span></span></code></pre></div><p>The page still lists every entry. Submitting a valid signature does not redirect: <code>append</code> fails inside Rust with a <code>PermissionDenied</code> error before SQLite is touched, the rejection reaches the application as a JavaScript <code>Error</code> named <code>PermissionDenied</code>, and the application&#39;s request listener answers <code>500 Internal Server Error</code> while logging the error, with that name, to the host&#39;s standard error. The database file is byte-for-byte unchanged, which <code>entries</code> and a file hash both confirm.</p><p>Read-only is enforced where the operation happens, not by hiding the function: the guest can still call <code>append</code>, and the host refuses it.</p><h3 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to “Verify”">​</a></h3><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">cargo</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> test</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> -p</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> bento_guestbook_host</span></span></code></pre></div><p>The tests exercise the real guest book, in-process and as the spawned binary, in both modes: rendering and assets, signing and validation, persistence across instance disposal and host restarts, <code>--read-only</code>, instance isolation, signal shutdown with the port rebinding, and the guest&#39;s inability to read the store. They run against a disposable copy of the fixture under <code>/tmp/bento-host/fixture</code>, mirrored with <code>rsync</code> and installed with <code>pnpm install --frozen-lockfile</code> on first use, and launch every guest without <code>NODE_PATH</code>.</p><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to “Worked example”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>$ target/release/bento-guestbook-host serve --project fixtures/remix-guest-book --database /tmp/guest-book.db --port 1612</span></span>
<span class="line"><span>Server running at http://localhost:1612</span></span>
<span class="line"><span></span></span>
<span class="line"><span># In a browser: sign as &quot;Ada Lovelace&quot; with the message &quot;Hello from 1843&quot;, see the entry listed.</span></span>
<span class="line"><span>^C</span></span>
<span class="line"><span>shutdown: graceful (exit code 0)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ target/release/bento-guestbook-host entries --database /tmp/guest-book.db</span></span>
<span class="line"><span>{&quot;id&quot;:1,&quot;name&quot;:&quot;Ada Lovelace&quot;,&quot;message&quot;:&quot;Hello from 1843&quot;,&quot;createdAt&quot;:&quot;2026-10-10T18:30:05Z&quot;}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ target/release/bento-guestbook-host serve --project fixtures/remix-guest-book --database /tmp/guest-book.db --read-only</span></span>
<span class="line"><span>Server running at http://localhost:1612</span></span>
<span class="line"><span></span></span>
<span class="line"><span># The browser still shows Ada&#39;s entry; signing again answers 500, the host&#39;s stderr shows</span></span>
<span class="line"><span># PermissionDenied: the guest book is read-only, and the file is unchanged.</span></span></code></pre></div><h2 id="how-this-generalizes" tabindex="-1">How this generalizes <a class="header-anchor" href="#how-this-generalizes" aria-label="Permalink to “How this generalizes”">​</a></h2><p>A host module is the embedding API, not guest-book support in the runtime. Any Rust application registers its own modules the same way: choose a <code>host:</code> name, supply asynchronous functions over JSON values, and hand the registration to the runtime configuration before loading the entry module. The runtime resolves the specifier only for the instance that registered it; another instance in the same process, or the <code>bento</code> command, gets a resolution error with no package or network fallback, while the registering instance keeps serving.</p><p>Errors cross the boundary as rejected promises carrying the Rust error&#39;s name, so a guest can distinguish a refused operation from a crashed one. Grants are enforced at the native boundary regardless of what a module exposes: handing the guest <code>host:guestbook</code> does not let it open the database file, and would not even if the module returned the path.</p><p>Replacing the storage behind <code>host:guestbook</code> changes only this example. The runtime, the resolver, the transforms, and the application&#39;s router, validation, rendering, and browser components stay the same.</p><h2 id="limits-and-edge-cases" tabindex="-1">Limits and edge cases <a class="header-anchor" href="#limits-and-edge-cases" aria-label="Permalink to “Limits and edge cases”">​</a></h2><ul><li>Building the example needs the pinned Rust toolchain. Preparing the project needs pnpm and Node, which the fixture&#39;s package tools use; serving it afterwards needs only the built executable, the project files, and its installed dependencies. The tests also need <code>rsync</code>.</li><li><code>--read-only</code> opens the database read-only and therefore needs it to exist. Run <code>serve</code> without the flag once, or point at a store <code>entries</code> can already read.</li><li>The database must be outside every granted read path: the project directory and each <code>node_modules</code> directory beside or above it. <code>serve</code> refuses a <code>--database</code> whose resolved path lies under one of them, and the examples above use <code>/tmp/guest-book.db</code> for that reason.</li><li>Granting the package lookup locations grants whatever they resolve to. An ancestor whose <code>node_modules</code> is a symlink, as this repository&#39;s worktrees link theirs from the main checkout, makes the link&#39;s whole target tree readable; an ancestor other users can write to, such as a shared temporary directory, lets them place a readable <code>node_modules</code> there. Serve from a project whose ancestors you trust.</li><li>The host&#39;s table is its own. It does not read the application&#39;s <code>db/</code> migrations or the <code>guest_book</code> table that the <code>node:sqlite</code> path creates, and the two storage paths do not share a file.</li><li>The host module accepts entries, not SQL: <code>append</code> takes a <code>name</code> and a <code>message</code>; the host assigns <code>id</code> and <code>createdAt</code>. Validation of the fields stays in the application.</li><li>Enabling the native compiler addons runs trusted native code in the host process. The grants contain the application&#39;s JavaScript, not an arbitrary addon, and native code reads the host&#39;s own environment, which is why <code>NODE_PATH</code> must not be set.</li><li>Shutdown that reaches the five-second deadline is reported as <code>interrupted</code>, never as graceful, and the interrupted instance is disposed rather than reused.</li></ul>`,46)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};